build_app() { ver=$(grep -o "const string Version = \"[0-9.]*\"" YtToMp3.cs | grep -o "[0-9][0-9.]*"); sed -i "s/AssemblyVersion(\"[0-9.]*\")/AssemblyVersion(\"$ver.0\")/; s/AssemblyFileVersion(\"[0-9.]*\")/AssemblyFileVersion(\"$ver.0\")/" AssemblyInfo.cs; rm -f YtToMp3.exe "Purphex Music.exe"; "$CSC" -nologo -target:winexe -win32icon:app.ico -win32manifest:app.manifest -resource:logo.png,Purphex.logo.png -out:"Purphex Music.exe" $L $SRC 2>&1 | grep -i error | head -${1:-12}; test -f "Purphex Music.exe" && cp -f "Purphex Music.exe" YtToMp3.exe && echo BUILD_OK; }
build_check() { "$CSC" -nologo -target:winexe -out:_try.exe $L $SRC 2>&1 | grep -i error | head -${1:-12}; rm -f _try.exe; }
data_backup() { D="$LOCALAPPDATA/YtToMp3"; B="$TEMP/ytdata_backup"; rm -rf "$B"; mkdir -p "$B"; cp -a "$D"/*.txt "$B"/ 2>/dev/null; for d in covers synthpresets themes; do [ -d "$D/$d" ] && cp -a "$D/$d" "$B"/; done; }
data_restore() { D="$LOCALAPPDATA/YtToMp3"; B="$TEMP/ytdata_backup"; [ -d "$B" ] || return; rm -f "$D"/*.txt; cp -a "$B"/*.txt "$D"/ 2>/dev/null; for d in covers synthpresets themes; do rm -rf "$D/$d"; [ -d "$B/$d" ] && cp -a "$B/$d" "$D"/; done; }
run_tests() { S="$LOCALAPPDATA/YtToMp3/settings.txt"; data_backup; cp -f "$S" "$S.keep" 2>/dev/null; ok=1; for t in "T StudioTest" "V VstTest" "W3 Vst3Test" "U UiTest" "S StudioUiTest" "Z SoundsTest" "SQ SoundQualityTest" "Q SoundsUiTest" "P PlugTest" "F FlexTest" "G FlexUiTest" "Y SynthTest" "D DawTest" "K ClipsTest" "CP CommPresetsTest" "AU ScreenAudit" "PR ProjectsTest" "CK ClickTest" "ED EditionTest" "MT MicTest" "FT FontTest" "LT LyricsTest" "UT UsageTest" "CM ColourMixTest" "NF NewFeatTest" "PP ProfPersistTest" "SO SocialTest" "CA ContrastAudit" "GF GlitchTest" "PX PxTest" "CRTEST CreativeTest" "IN InspectorTest" "LB LibraryTest" "PR PianoRollTest"; do set -- $t; rm -f $2.exe; "$CSC" -nologo -main:$1 -resource:logo.png,Purphex.logo.png -out:$2.exe $L $SRC $2.cs 2>&1 | grep -i error; r=$(timeout 600 ./RunHidden.exe $2.exe 2>&1 | tail -1); echo "$2: $r"; case "$r" in *" 0 failed"*) ;; *failed*|*FAILED*) ok=0;; *passed*) ;; *) ok=0;; esac; done; echo ok=$ok; test -f "$S.keep" && cp -f "$S.keep" "$S" && rm -f "$S.keep"; data_restore; rm -f "$USERPROFILE/Music/yt2mp3/Recordings/"Recording\ 2026-*.wav; rmdir "$USERPROFILE/Music/yt2mp3/Recordings" 2>/dev/null; }
write_manifest() { h=$(sha256sum YtToMp3.exe | cut -d' ' -f1); printf '%s\nhttps://github.com/heaththomas225-svg/yt-to-mp3/releases/latest/download/YtToMp3.exe\n%s\nsha256=%s\n' "$1" "$2" "$h" > version.txt; cp -f YtToMp3.exe "Purphex Music.exe"; echo "sha256 $h"; }
